E = html.escape
NAME = 'Mohammad Masudur Rahman'
AREAS = {'human-ai':'Human–AI interaction','nlp':'NLP & language technologies','applied-ml':'Applied machine learning'}
def authors(s):
    return E(s).replace(NAME, '<strong>'+NAME+'</strong>').replace('M. M. Rahman', '<strong>M. M. Rahman</strong>')
def link(p):
    u=p.get('url') or 'https://scholar.google.com/scholar?q='+quote('"'+p['title']+'"')
    label=p.get('link_label','Find paper')
    return f'<a href="{E(u)}" target="_blank" rel="noopener noreferrer">{E(label)} <span aria-hidden="true">↗</span></a>'
def year(p): return str(p['year']) if p['year'] else '—'
def bib(p):
    names=p['authors'].replace(', and ', ', ').replace(' and ', ', ').split(', ')
    fields={'title':p['title'],'author':' and '.join(names)}
    if p['year']: fields['year']=str(p['year'])
    fields['journal' if p['citation_type']=='article' else 'booktitle' if p['citation_type'] in ('inproceedings','incollection') else 'note']=p['venue']
    if p.get('doi'): fields['doi']=p['doi']
    if p.get('url'): fields['url']=p['url']
    return '@'+p['citation_type']+'{rahman_'+p['id'].replace('-','_')+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items())+'\n}'
def row(p,selected=False):
    badge=f'<span class="badge {"preprint" if p["type"] in ("Preprint","Manuscript") else ""}">{E(p["type"])}</span>'
    content=f'''<div class="paper-meta">{badge}<span>{year(p) if selected else E(AREAS[p['area']])}</span></div>
    <h3>{E(p['title'])}</h3><p class="authors">{authors(p['authors'])}</p><p class="venue">{E(p['venue'])}{'' if selected or not p['year'] else ' · '+year(p)}</p>
    {f'<p class="paper-summary">{E(p["summary"])}</p>' if selected and p.get('summary') else ''}
    <div class="paper-links">{link(p) if p['type']!='Manuscript' else '<span>Publication details pending</span>'}<button type="button" class="citation-toggle js-only" hidden data-cite="{p['id']}" aria-label="Cite {E(p['title'])}">Cite</button></div>'''
    if selected: return f'<article class="selected-paper">{content}</article>'
    return f'<article class="pub-row" id="pub-{p["id"]}" data-area="{p["area"]}" data-type="{p["type"]}" data-search="{E((p["title"]+" "+p["authors"]+" "+p["venue"]+" "+year(p)).lower())}"><div class="pub-year">{year(p)}</div><div>{content}</div></article>'
